manifest.newHelper:
import type {Resource} from '../resource.js';
import type {StaticDownloadOptions} from '../options.js';

/** Read the requested remote timestamp in seconds; callers decide when to apply it. */
export function remoteLastModifiedTime(res: Resource, options: StaticDownloadOptions): number | undefined {
  // https://github.com/website-local/website-scrap-engine/issues/174
  if (options.preferRemoteLastModifiedTime && res.meta?.headers?.['last-modified']) {
    return Date.parse(res.meta.headers['last-modified']) / 1000;
  }
}

rangeFunctions.loop:
export function isBytesAccepted(acceptRange) {
    if (!acceptRange) {
        return false;
    }
    const ranges = acceptRange.split(',');
    for (let i = 0; i < ranges.length; i++) {
        if (ranges[i] === 'bytes') {
            return true;
        }
    }
    return false;
}

rangeFunctions.includes:
export function isBytesAccepted(acceptRange) {
  return acceptRange?.split(',').includes('bytes') ?? false;
}

